        helpers.appendChild(card);
    }
    // game credits — pull thumbnails from the catalog so cards match
    games.innerHTML = '';
    const all = [{ name: 'pizza tower', img: 'https://pizza-tower-9iw.pages.dev/assets/btn-pizzatower.png' }, ...MODS, ...FANGAMES];
    for (const g of all) {
