<script>
// Shared site music — plays on every site page (not game pages),
// resumes its position so it feels continuous when navigating.

// Site themes: bg = background image, song = music track.
// cls = optional extra class on .bgimg.
const PU_THEMES = [
    { name: 'pizzascare',     bg: 'https://pizza-tower-9iw.pages.dev/assets/halloween.png',     song: 'https://pizza-tower-9iw.pages.dev/assets/theme-halloween.ogg' },
    { name: 'the tower',      bg: 'https://pizza-tower-9iw.pages.dev/assets/bg.gif',            song: 'https://pizza-tower-9iw.pages.dev/assets/theme.mp3' },
    { name: 'oregano desert', bg: 'https://pizza-tower-9iw.pages.dev/assets/bg-desert.webp',    song: 'https://pizza-tower-9iw.pages.dev/assets/theme-desert.ogg' },
    { name: 'pizzaland',      bg: 'https://pizza-tower-9iw.pages.dev/assets/bg-pizzaland.webp', song: 'https://pizza-tower-9iw.pages.dev/assets/theme-funiculi.ogg' },
    { name: "what's with these pizza guys?", bg: 'https://pizza-tower-9iw.pages.dev/assets/bg-pizzaguys.png', song: 'https://pizza-tower-9iw.pages.dev/assets/theme-pizzaguys.mp3' },
];

const puTheme = PU_THEMES.find(t => t.name === localStorage.getItem('pu_theme')) || PU_THEMES[0];

// apply the theme's background on every page that loads this script
const bgimgEl = document.querySelector('.bgimg');
if (bgimgEl) {
    bgimgEl.src = puTheme.bg;
    bgimgEl.className = 'bgimg ' + (puTheme.cls || '');
}

const bgm = new Audio(puTheme.song);
bgm.loop = true;
bgm.volume = localStorage.getItem('pu_vol') != null ? +localStorage.getItem('pu_vol') / 100 : 1;
const bgmWanted = localStorage.getItem('pu_audio') !== 'off';
const bgmPos = +localStorage.getItem('pu_pos') || 0;
let bgmStarted = false;

function kickBgm() {
    // dataset.gameOpen = a game is open in the overlay — never start over it
    if (bgmStarted || !bgmWanted || document.body.dataset.gameOpen) return;
    try { bgm.currentTime = bgmPos; } catch {}
    bgm.play()
        .then(() => {
            bgmStarted = true;
            document.removeEventListener('click', kickBgm);
            document.removeEventListener('keydown', kickBgm);
        })
        .catch(() => {}); // autoplay blocked — wait for an interaction
}
document.addEventListener('click', kickBgm);
document.addEventListener('keydown', kickBgm);
kickBgm(); // try immediately — allowed once the site has been interacted with before

// keep position saved so the next page picks up where this one left off
setInterval(() => { if (bgmStarted) localStorage.setItem('pu_pos', bgm.currentTime); }, 2000);
window.addEventListener('beforeunload', () => {
    if (bgmStarted) localStorage.setItem('pu_pos', bgm.currentTime);
});

</script>
<script>
/* Pizza Unblocked — device detection.
   Sets window.PU_DEVICE to 'mobile' or 'pc', tags <body> with
   device-mobile / device-pc, and fills #devLine where present. */
(function () {
    const ua = navigator.userAgent;
    const mobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini|Mobile/i.test(ua)
        || ((navigator.maxTouchPoints || 0) > 1 && window.matchMedia && matchMedia('(pointer: coarse)').matches);
    window.PU_DEVICE = mobile ? 'mobile' : 'pc';
    document.documentElement.classList.add('device-' + window.PU_DEVICE);
    if (document.body) document.body.classList.add('device-' + window.PU_DEVICE);
    else addEventListener('DOMContentLoaded', () => document.body.classList.add('device-' + window.PU_DEVICE));
    const el = document.getElementById('devLine');
    if (el) el.textContent = 'device: ' + window.PU_DEVICE + (mobile ? ' (touch controls on in games)' : '');
})();

</script>
<script>
// shared card renderer + sfx for mods/extras pages
function renderCards(gridEl, emptyEl, list) {
    for (const g of list) {
        const a = document.createElement('a');
        a.className = 'card';
        a.href = 'games/' + g.dir + '/';
        a.innerHTML =
            `<div class="thumb"><img src="${g.img}" alt="${g.name}"><button class="dots" tabindex="-1">⋮</button></div>` +
            `<div class="cname">${g.name}</div>`;
        gridEl.appendChild(a);
    }
    emptyEl.hidden = list.length > 0;
}

function setupSearch(inputEl, gridEl, emptyEl, list) {
    if (!inputEl) return;
    inputEl.addEventListener('input', () => {
        const q = inputEl.value.trim().toLowerCase();
        gridEl.innerHTML = '';
        renderCards(gridEl, emptyEl, q ? list.filter(g => g.name.toLowerCase().includes(q)) : list);
    });
}

// hover sfx
const hoverSfx = new Audio('https://pizza-tower-9iw.pages.dev/assets/sfx/buttons.ogg');
hoverSfx.volume = 0.6;
hoverSfx.preload = 'auto';
document.addEventListener('mouseover', (e) => {
    if (e.target.closest('.card, .icon-btn, .pizza-icon')) {
        hoverSfx.currentTime = 0;
        hoverSfx.play().catch(() => {});
    }
});

</script>
